// Ersatz spaeter: STEP-Parser-Output von SCRUM-29 (Gruppe A (CAD))
// Real waere: import_cad_file(stationFilePath) -> get_all_objects()
// ============================================================

const assembly = {
  anlage: "2-Foerderer_1-Drehtisch",
  format_quelle: "STEP (ISO 10303-21)",
  stationFilePath: "C:\\CAD\\Conveyor_System\\2-Foerderer_1-Drehtisch.stp",
  objekte: [
    { id: "obj_001", ursprungsname: "C26312.00-1_Adapter:1", inventor_tags: { Objektname: null, Simulationstyp: null, JointType: null }, typ_hint: "Adapter" },
    { id: "obj_010", ursprungsname: "Foerderband_RB01:1", inventor_tags: { Objektname: "RB01", Simulationstyp: "Surface", JointType: null }, position: { x: 0, y: 0, z: 1 } },
    { id: "obj_011", ursprungsname: "Foerderband_RB02:1", inventor_tags: { Objektname: "RB02", Simulationstyp: "Surface", JointType: null }, position: { x: 2, y: 0, z: 1 } },
    { id: "obj_012", ursprungsname: "Foerderband_RB03:1", inventor_tags: { Objektname: "RB03", Simulationstyp: "Surface", JointType: null }, position: { x: 4, y: 0, z: 1 } },
    { id: "obj_020", ursprungsname: "Drehtisch_1315035-1:1", inventor_tags: { Objektname: "DT01", Simulationstyp: "Motorisiert", JointType: "RevoluteJoint" }, position: { x: 3, y: 0, z: 1 } },
    { id: "obj_030", ursprungsname: "1791275-1_Naeherungsschalter:1", inventor_tags: { Objektname: "Sensor_NSE1", Simulationstyp: "Sensor", JointType: null }, position: { x: 0.5, y: 0.2, z: 1.2 } },
    { id: "obj_031", ursprungsname: "1791275-1_Naeherungsschalter:2", inventor_tags: { Objektname: "Sensor_NSE2", Simulationstyp: "Sensor", JointType: null }, position: { x: 1.8, y: 0.2, z: 1.2 } },
    { id: "obj_032", ursprungsname: "C77102.00-1_Sensorhalter:1", inventor_tags: { Objektname: null, Simulationstyp: null, JointType: null } },
    { id: "obj_040", ursprungsname: "C81289.00-1_Staender:1", inventor_tags: { Objektname: null, Simulationstyp: null, JointType: null } }
  ]
};

const surfaces = assembly.objekte.filter(o => o.inventor_tags.Simulationstyp === "Surface");
const motorisiert = assembly.objekte.filter(o => o.inventor_tags.Simulationstyp === "Motorisiert");
const sensoren = assembly.objekte.filter(o => o.inventor_tags.Simulationstyp === "Sensor");

return [{
  json: {
    assembly,
    assembly_json: JSON.stringify(assembly, null, 2),
    stats: {
      objekte_total: assembly.objekte.length,
      surfaces: surfaces.length,
      motorisiert: motorisiert.length,
      sensoren: sensoren.length,
      ohne_tags: assembly.objekte.filter(o => !o.inventor_tags.Objektname).length
    },
    timestamp: new Date().toISOString()
  }
}];

// Plan aus tool_use Block extrahieren
const response = $json;
let plan = null;
let tokens = { in: 0, out: 0 };
try {
  const block = response.content.find(c => c.type === 'tool_use');
  plan = block ? block.input : null;
  tokens.in = response.usage?.input_tokens || 0;
  tokens.out = response.usage?.output_tokens || 0;
} catch (e) {
  return [{ json: { error: 'Plan-Extraktion fehlgeschlagen: ' + e.message, raw: response } }];
}
if (!plan) return [{ json: { error: 'Kein tool_use Block', raw: response } }];

return [{
  json: {
    plan,
    plan_json: JSON.stringify(plan, null, 2),
    tokens_plan: tokens,
    rolle: 'plan'
  }
}];

// FIX Bug 2: Plan mit Rolle 'plan' in Merge einspeisen
// Damit Logic Builder + Sammle alle Calls den Plan via Aggregate finden
return [{
  json: {
    rolle: 'plan',
    plan: $json.plan,
    plan_json: $json.plan_json,
    tokens_plan: $json.tokens_plan
  }
}];

