// Logic-Builder Tool-Use extrahieren + alle Calls aus Aggregate ziehen
const response = $json;
let logic_calls = [];
let tokens = { in: 0, out: 0 };
let error = null;
try {
  const block = response.content.find(c => c.type === 'tool_use');
  if (block && block.input && Array.isArray(block.input.calls)) logic_calls = block.input.calls;
  else error = 'Logic Builder: kein tool_use';
  tokens.in = response.usage?.input_tokens || 0;
  tokens.out = response.usage?.output_tokens || 0;
} catch (e) { error = e.message; }

// Alle Calls aus Aggregate holen (inkl. Plan jetzt via Tag Plan)
const prev = $('Aggregate Transform').first().json.data || [];
const rename_calls = (prev.find(d => d.rolle === 'renamer') || {}).calls || [];
const type_calls   = (prev.find(d => d.rolle === 'typer')   || {}).calls || [];
const joint_calls  = (prev.find(d => d.rolle === 'joint')   || {}).calls || [];
const plan_item    = prev.find(d => d.rolle === 'plan') || {};

return [{
  json: {
    plan: plan_item.plan || null,
    all_calls: {
      rename: rename_calls,
      type: type_calls,
      joint: joint_calls,
      logic: logic_calls
    },
    counts: {
      rename: rename_calls.length,
      type: type_calls.length,
      joint: joint_calls.length,
      logic: logic_calls.length,
      total: rename_calls.length + type_calls.length + joint_calls.length + logic_calls.length
    },
    tokens_logic: tokens,
    error_logic: error
  }
}];

// MCP Executor (Platzhalter)
// TODO bei MCP-Anbindung von Gruppe B (MCP) (Grp B):
//   - HTTP POST an MCP-Endpoint pro Call
//   - Sequence: rename -> type -> joint -> logic (MUSS in dieser Reihenfolge)
//   - Bei create_button/create_logic_object: Response-ID fuer link_objects merken
//   - Fehlerbehandlung + Rollback pro Call

const data = $json;
const all_calls = data.all_calls || {};

const execution_log = [];
const sequence = ['rename', 'type', 'joint', 'logic'];
for (const phase of sequence) {
  const calls = all_calls[phase] || [];
  for (const call of calls) {
    execution_log.push({
      phase,
      tool: call.tool || phase,
      params: call,
      status: 'simulated_ok',
      timestamp: new Date().toISOString()
    });
  }
}

return [{
  json: {
    plan: data.plan,
    all_calls,
    counts: data.counts,
    tokens_logic: data.tokens_logic,
    execution_log,
    execution_summary: {
      total: execution_log.length,
      simulated: execution_log.length,
      failed: 0,
      mcp_endpoint: 'PLACEHOLDER – wird durch fe.screen-sim MCP-URL ersetzt sobald Gruppe B (MCP) (Grp B) Endpoint liefert'
    }
  }
}];

// Bericht extrahieren + persist (3 Dateien: md + calls.json + meta.json)
const response = $json;
let bericht = '';
let tokens = { in: 0, out: 0 };
try {
  const block = response.content.find(c => c.type === 'text');
  bericht = block ? block.text : JSON.stringify(response);
  tokens.in = response.usage?.input_tokens || 0;
  tokens.out = response.usage?.output_tokens || 0;
} catch (e) { bericht = 'Validator-Fehler: ' + e.message; }

const ctx = $('MCP Executor (Platzhalter)').first().json;
const ts = new Date().toISOString().replace(/[:.]/g,'-').replace(/T/,'_').slice(0,19);
const basepath = '/Users/stm/Desktop/UNI/Master/1. Semester/Project Data Eng ZOLLERN/SCRUM-40/runs_phase2';

const fs = require('fs');
const path = require('path');
let write_status = 'ok';
try {
  fs.mkdirSync(basepath, { recursive: true });
  fs.writeFileSync(path.join(basepath, ts + '.md'), bericht);
  fs.writeFileSync(path.join(basepath, ts + '.calls.json'), JSON.stringify(ctx.all_calls, null, 2));
  fs.writeFileSync(path.join(basepath, ts + '.meta.json'), JSON.stringify({
    timestamp: new Date().toISOString(),
    workflow_version: 'phase2_v2',
    counts: ctx.counts,
    execution_summary: ctx.execution_summary,
    tokens_validator: tokens,
    plan_surfaces: (ctx.plan?.surfaces_for_logic || []).length
  }, null, 2));
} catch (e) { write_status = 'failed: ' + e.message; }

console.log('=== ZOLLERN Phase 2 Bericht ===');
console.log('Persistiert: ' + basepath + '/' + ts + '.{md,calls.json,meta.json}');
console.log(bericht);

return [{ json: { bericht, tokens_validator: tokens, write_status, persist_dir: basepath, timestamp: ts, status: 'fertig' } }];
